import { Flags } from '@oclif/core';
import { WORKFLOW_INSTANCE_TYPE, assertReadableModel, documentPrefilter, inFlightFilter, instanceWatchesDocument, tagScopeFilter, terminalState, } from '@sanity/workflow-engine';
import logSymbols from 'log-symbols';
import { WorkflowCommand } from "../../lib/base-command.js";
import { resolveReadTargets } from "../../lib/context.js";
import { failOnThrow } from "../../lib/fail.js";
import { jsonFlags, tagFlags } from "../../lib/flags.js";
import { logJsonListing, runReadAcrossTargets } from "../../lib/read-fanout.js";
import { formatAge, logClippedTable } from "../../lib/ui.js";
const DOCUMENT_LIST_PROJECTION = `{
  _type,
  _id,
  workflowResource,
  modelVersion,
  minReaderModel,
  definition,
  tag,
  currentStage,
  fields,
  stages,
  ancestors,
  subworkflows,
  completedAt,
  abortedAt,
  lastChangedAt
}`;
export function buildListQuery(flags) {
    const filters = [`_type == "${WORKFLOW_INSTANCE_TYPE}"`];
    const params = {};
    if (!flags['include-completed'])
        filters.push(inFlightFilter());
    if (flags.definition) {
        filters.push('definition == $definition');
        params['definition'] = flags.definition;
    }
    if (flags.failed)
        filters.push('count(stages[].activities[status == "failed"]) > 0');
    if (flags.tag) {
        filters.push(tagScopeFilter());
        params['tag'] = flags.tag;
    }
    if (flags.document) {
        const armParams = {};
        filters.push(`(${documentPrefilter([flags.document], armParams)})`);
        Object.assign(params, armParams);
        params['limit'] = flags.limit + 1;
        return {
            groq: `*[${filters.join(' && ')}] | order(lastChangedAt desc)[0...$limit]${DOCUMENT_LIST_PROJECTION}`,
            params,
        };
    }
    params['limit'] = flags.limit + 1;
    const groq = `*[${filters.join(' && ')}] | order(lastChangedAt desc) [0...$limit]{
      _id,
      definition,
      tag,
      currentStage,
      completedAt,
      abortedAt,
      lastChangedAt,
      modelVersion,
      minReaderModel
    }`;
    return { groq, params };
}
export function instanceRow(r) {
    return {
        _id: r._id,
        definition: r.definition,
        tag: r.tag,
        currentStage: r.currentStage,
        status: terminalState({
            ...(r.completedAt != null ? { completedAt: r.completedAt } : {}),
            ...(r.abortedAt != null ? { abortedAt: r.abortedAt } : {}),
        }),
        lastChangedAt: r.lastChangedAt,
    };
}
export default class List extends WorkflowCommand {
    static description = 'List workflow instances in the configured dataset (in-flight by default).';
    static examples = [
        '<%= config.bin %> workflows list',
        '<%= config.bin %> workflows list --include-completed',
        '<%= config.bin %> workflows list --definition productLaunch',
        '<%= config.bin %> workflows list --document dataset:proj:ds:article-1',
        '<%= config.bin %> workflows list --tag prod',
        '<%= config.bin %> workflows list --json',
    ];
    static flags = {
        ...tagFlags,
        'include-completed': Flags.boolean({
            description: 'Include completed/aborted instances (default: in-flight only).',
            default: false,
        }),
        failed: Flags.boolean({
            description: 'Only instances with at least one failed activity.',
            default: false,
        }),
        definition: Flags.string({
            description: "Only instances of this workflow definition (its `name`; the instance's `definition` field).",
        }),
        document: Flags.string({
            description: 'Only instances that reference this document (resource-qualified GDR URI, ' +
                'e.g. "dataset:proj:ds:article-1").',
        }),
        limit: Flags.integer({
            description: 'Maximum rows to return.',
            default: 50,
        }),
        ...jsonFlags,
    };
    async run() {
        const { flags } = await this.parse(List);
        const targets = await resolveReadTargets(flags);
        const { groq, params } = failOnThrow('Invalid --document:', () => buildListQuery(flags));
        const document = flags.document;
        if (flags.json) {
            await logJsonListing({
                targets,
                key: 'instances',
                limit: flags.limit,
                log: (line) => this.log(line),
                fetch: ({ client }) => fetchRows({ client, groq, params, document, limit: flags.limit }),
                toRow: instanceRow,
            });
            return;
        }
        const failures = await runReadAcrossTargets({
            targets,
            log: (line) => this.log(line),
            run: async ({ client }) => {
                const fetched = await fetchRows({ client, groq, params, document, limit: flags.limit });
                if (fetched.rows.length === 0) {
                    if (fetched.hasMore) {
                        this.log(`${logSymbols.info} no matches in the first ${flags.limit} candidates — raise --limit to search further`);
                    }
                    else {
                        this.log(`${logSymbols.info} no instances match`);
                    }
                    return;
                }
                logClippedTable({
                    rows: fetched.rows,
                    limit: flags.limit,
                    moreAvailable: fetched.hasMore,
                    headers: ['instance', 'workflow', 'tag', 'stage', 'status', 'updated'],
                    toCells: (r) => {
                        const row = instanceRow(r);
                        return [
                            row._id,
                            row.definition,
                            row.tag,
                            row.currentStage,
                            row.status,
                            formatAge(row.lastChangedAt),
                        ];
                    },
                    log: (line) => this.log(line),
                });
            },
        });
        if (failures.length > 0) {
            this.exit(1);
        }
    }
}
export async function fetchRows({ client, groq, params, document, limit, }) {
    if (document === undefined) {
        const rows = await client.fetch(groq, params, { tag: 'list' });
        return { rows: rows.map(assertReadableModel), hasMore: rows.length > limit };
    }
    const candidates = await client.fetch(groq, params, { tag: 'list' });
    return {
        rows: candidates
            .map(assertReadableModel)
            .filter((instance) => instanceWatchesDocument(instance, document)),
        hasMore: candidates.length > limit,
    };
}
